BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(7);
INSERT INTO auth.users(id,email) VALUES('acacacac-0000-0000-0000-000000000001','reviewa@test.local'),('acacacac-0000-0000-0000-000000000002','reviewb@test.local');
INSERT INTO public.works(id,user_id,work_type,title,metadata) VALUES('acacacac-1000-0000-0000-000000000001','acacacac-0000-0000-0000-000000000001','book','Manual title','{"locked_fields":["title"]}');
INSERT INTO public.records(id,work_id,record_type,publisher,metadata) VALUES('acacacac-2000-0000-0000-000000000001','acacacac-1000-0000-0000-000000000001','edition','Manual publisher','{"locked_fields":["publisher","contributors"],"lookup_suggestions":{"keep":true}}');
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claims='{"sub":"acacacac-0000-0000-0000-000000000001","role":"authenticated"}';
SELECT public.apply_metadata_fields('acacacac-1000-0000-0000-000000000001','acacacac-2000-0000-0000-000000000001','{"title":"Stale model title","subtitle":"Reviewed subtitle"}','{"publisher":"Stale publisher"}','{"container_title":"Reviewed container"}');
SELECT is((SELECT title FROM public.works),'Manual title','current title lock wins over stale review');
SELECT is((SELECT subtitle FROM public.works),'Reviewed subtitle','unlocked field applied');
SELECT is((SELECT publisher FROM public.records),'Manual publisher','current record lock wins');
SELECT is((SELECT metadata->'lookup_suggestions' FROM public.records),'{"keep":true}'::jsonb,'metadata merge preserves private suggestions');
SELECT is(public.set_metadata_contributors('acacacac-2000-0000-0000-000000000001','[]'),false,'current contributor lock wins');
SET LOCAL request.jwt.claims='{"sub":"acacacac-0000-0000-0000-000000000002","role":"authenticated"}';
SELECT throws_ok($$SELECT public.apply_metadata_fields('acacacac-1000-0000-0000-000000000001','acacacac-2000-0000-0000-000000000001','{}','{}','{}')$$,'42501','record not owned','second user cannot apply fields');
RESET ROLE;
INSERT INTO public.jobs(id,user_id,job_type,payload,status,attempts,claim_generation,lease_expires_at) VALUES('acacacac-3000-0000-0000-000000000001','acacacac-0000-0000-0000-000000000001','extract_metadata_ai','{}','running',1,1,now()+interval '1 minute');
SELECT public.defer_ai_job('acacacac-3000-0000-0000-000000000001',1,'ai_disabled');
SELECT is((SELECT attempts FROM public.jobs WHERE id='acacacac-3000-0000-0000-000000000001'),0,'AI outage does not burn retries');
SELECT * FROM finish();
ROLLBACK;
